/**
 * messageType can be 'text', 'voice', or 'suggested-action'
 *
 * Event detail structure sent with the custom 'waa:sendPrompt' event:
 * {
 *   value: string,            // Required - The prompt text to send
 *   messageType?: string,     // Optional - 'text' | 'voice' | 'suggested-action'
 *   options?: object,         // Optional - Behavior control options
 *   metadata?: object         // Optional - Tracking metadata (NO PII)
 * }
 */

// This class listens for click events on elements with the specified class and dispatches a custom 'waa:sendPrompt' event with the appropriate detail when clicked.
// It also provides a method to clean up the event listener when it's no longer needed.
class OcWaaSendPromptEvent {

  constructor(opts) {
    this._el = opts.el;
    this._boundClickHandler = opts.customEventListener?.bind(this) ?? this._handleClick.bind(this);
    this._boundKeyDownHandler = this._handleKeyDown.bind(this);
    this._boundKeyUpHandler = this._handleKeyUp.bind(this);

    this._ensureFocusableButtonSemantics();

    this._el.addEventListener('click', this._boundClickHandler);
    this._el.addEventListener('keydown', this._boundKeyDownHandler);
    this._el.addEventListener('keyup', this._boundKeyUpHandler);
  }

  _ensureFocusableButtonSemantics() {
    if (this._el.getAttribute('role') === 'button' && !this._el.hasAttribute('tabindex')) {
      this._el.setAttribute('tabindex', '0');
    }
  }

  _handleClick(e) {
    e.preventDefault();

    // Create the event detail object with required properties.
    const eventDetail = {
      value: this._getPromptValue(),
      messageType: this._getMessageType(),
      options: this._getOptions()
    };

    const metadata = this._getMetadata();
    if (metadata) {
      eventDetail.metadata = metadata;
    }

    // Create and dispatch the custom event with the detail
    const event = new CustomEvent('waa:sendPrompt', { // new event being dispatched thats not supported yet, for testing use 'onAiSearchSubmit' event
      detail: eventDetail,
      bubbles: true,
      composed: true
    });

    // Dispatch the event from the element
    this._el.dispatchEvent(event);
  }

  _handleKeyDown(e) {
    if (e.key === ' ') {
      e.preventDefault();
      return;
    }

    if (e.key === 'Enter') {
      this._handleClick(e);
    }
  }

  _handleKeyUp(e) {
    if (e.key === ' ') {
      this._handleClick(e);
    }
  }

  // Get data-prompt-value attribute value from the element and use it as the value in the event detail
  _getPromptValue() {
    return this._el.dataset.promptValue || '';
  }

  // Get data-waa-message-type attribute value from the element and use it as the messageType in the event detail
  _getMessageType() {
    return this._el.dataset.waaMessageType || 'text';
  }

  // Get data-auto-send attribute value from the element
  _getAutoSend() {
    return this._el.dataset.autoSend === 'true';
  }

  // Build the options object with behavior derived from promptValue and autoSend.
  // Additional authored options can be set via data-waa-options attribute.
  _getOptions() {
    let options = {};
    try {
      options = this._el.dataset.waaOptions ? JSON.parse(this._el.dataset.waaOptions) : {};
    } catch (e) {
      console.error('Failed to parse waa options:', e);
    }
    options.behavior = this._getBehavior();
    return options;
  }

  // Derive the behavior from promptValue and autoSend
  _getBehavior() {
    if (!this._getPromptValue()) return 'open-only';
    return this._getAutoSend() ? 'submit' : 'insert';
  }

  // Metadata is optional. If provided, it must include a non-empty `value` field.
  _getMetadata() {
    const metadata = this._el.dataset.waaMetadata;

    if (!metadata) {
      return null;
    }

    try {
      const parsedMetadata = JSON.parse(metadata);

      if (typeof parsedMetadata !== 'object' || parsedMetadata === null || Array.isArray(parsedMetadata)) {
        console.error('WAA metadata must be a JSON object with a value field.');
        return null;
      }

      if (!Object.prototype.hasOwnProperty.call(parsedMetadata, 'value')) {
        console.error('WAA metadata must include a value field.');
        return null;
      }

      return parsedMetadata;
    } catch (e) {
      console.error('Failed to parse waa metadata:', e);
      return null;
    }
  }

  // Remove the event listener when the instance is no longer needed
  destroy() {
    this._el.removeEventListener('click', this._boundClickHandler);
    this._el.removeEventListener('keydown', this._boundKeyDownHandler);
    this._el.removeEventListener('keyup', this._boundKeyUpHandler);
  }
}

// Initialize the event listener for all elements with the class 'oc-waa-send-prompt' when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  const waaSendPromptClass = 'oc-waa-send-prompt';
  const chatDrawer = document.querySelector('#waaModern');

  const elements = document.querySelectorAll(`.${waaSendPromptClass}`);

  if (chatDrawer) {
    // Create an instance of OcWaaSendPromptEvent for each element with the specified class to set up the event listeners
    const instances = [];
    elements.forEach(element => {
      instances.push(new OcWaaSendPromptEvent({ el: element }));
    });
  } else {
    // Disable WAA send prompt links when the WAA drawer is not present on the page
    elements.forEach(element => {
      element.classList.add('disabled');
      if (element.tagName.toLowerCase() === 'a') {
        element.setAttribute('aria-disabled', 'true');
        element.setAttribute('tabindex', '-1');
        element.addEventListener('click', (e) => e.preventDefault());
      } else if (element.tagName.toLowerCase() === 'button') {
        element.setAttribute('disabled', 'true');
      }
    });
  }
}); 